#include "openfhe.h"
#include <fstream>
#include <iostream>
#include <iomanip>
using namespace lbcrypto;
int main(){try{CCParams<CryptoContextBGVRNS> p;p.SetPlaintextModulus(65537);p.SetRingDim(32768);p.SetMultiplicativeDepth(23);p.SetSecurityLevel(HEStd_128_classic);p.SetSecretKeyDist(UNIFORM_TERNARY);p.SetMultipartyMode(FIXED_NOISE_MULTIPARTY);p.SetScalingTechnique(FLEXIBLEAUTOEXT);p.SetKeySwitchTechnique(BV);p.SetDigitSize(8);p.SetEvalAddCount(1);p.SetKeySwitchCount(7);auto c=GenCryptoContext(p);auto cp=std::dynamic_pointer_cast<CryptoParametersBGVRNS>(c->GetCryptoParameters());if(c->GetRingDimension()!=32768||cp->GetStdLevel()!=HEStd_128_classic)throw std::runtime_error("security/profile mismatch");unsigned bits=cp->GetElementParams()->GetModulus().GetMSB();if(StdLatticeParm::FindRingDim(HEStd_ternary,HEStd_128_classic,bits)>32768)throw std::runtime_error("independent standard-table recheck");std::ifstream maps("/proc/self/maps");std::string line;unsigned loaded=0;while(std::getline(maps,line))if(line.find("libOPENFHE")!=std::string::npos){if(line.find("/workspace/fhe-deps/install-bound-prime-study/lib/")==std::string::npos)throw std::runtime_error("mixed/original SDK loaded");loaded++;}if(!loaded)throw std::runtime_error("no loaded library provenance");std::cout<<"{\"status\":\"CUSTOM_CONTEXT_PARAMETERS_ONLY\",\"p\":65537,\"ring\":32768,\"depth\":23,\"digit\":8,\"switches\":7,\"adds\":1,\"actual_Q_bits\":"<<bits<<",\"sigma\":"<<std::setprecision(17)<<cp->GetDistributionParameter()<<",\"alpha\":"<<cp->GetAssuranceMeasure()<<",\"threshold_parties\":"<<cp->GetThresholdNumOfParties()<<",\"q\":[";bool f=true;for(auto&q:cp->GetElementParams()->GetParams()){if(!f)std::cout<<',';f=false;std::cout<<q->GetModulus();}std::cout<<"],\"encrypted_circuit_tested\":false,\"security_proven\":false}"<<std::endl;}catch(const std::exception&e){std::cout<<"{\"status\":\"FAILED\",\"reason\":"<<std::quoted(e.what())<<"}"<<std::endl;return 1;}}
